typedef float rational_t;

class vector3d
{
public:
  rational_t x, y, z;

  vector3d() {}

  vector3d& operator=( const vector3d& v )
  {
    x = v.x;
    y = v.y;
    z = v.z;
    return *this;
  }
};

inline rational_t dot( const vector3d& a, const vector3d& b )
{
  rational_t t = a.x*b.x + a.y*b.y + a.z*b.z;
  return t;
}

class partition3
{
protected:
  rational_t d;
  vector3d normal;

public:
  const vector3d& get_normal() const { return normal; }
  rational_t distance( const vector3d& p ) const { return dot(p,normal)-d; }
};

bool collide_sphere_two_partition3s( const vector3d& pos, rational_t r,
                                     const partition3& h1,
                                     const partition3& h2,
                                     vector3d& hit_point );

bool collide_sphere_three_partition3s_almost_parallel( const vector3d& pos, rational_t r,
                                                       const partition3& h1,
                                                       const partition3& h2,
                                                       const partition3& h3,
                                                       vector3d& hit_point )
{
  vector3d hit_point1, hit_point2;

  if ( !collide_sphere_two_partition3s(pos, r, h1, h3, hit_point1)
       || !collide_sphere_two_partition3s(pos, r, h2, h3, hit_point2) )
    return false;

  if ( dot(h1.get_normal(), h2.get_normal()) >= 0.0f )
    hit_point = h1.distance(pos) < h2.distance(pos) ? hit_point2 : hit_point1;
  else
    hit_point = h1.distance(pos) < 0.0f ? hit_point2 : hit_point1;

  return true;
}
